// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the high-level architecture of this hotel reservation system.", "I split it into a read path and a write path. The read path is the search service. It queries a denormalised availability and rate cache that Kafka consumers keep fresh, so heavy browsing never touches the inventory database. The write path starts in the booking service. It creates a pending reservation with an idempotency key and runs a saga: hold inventory, take payment, confirm. The inventory service owns room_type-night rows in a relational database and uses conditional updates, so it is the source of truth. Every change writes an outbox row, and a relay publishes it to Kafka. From there, search, notifications and the channel manager consume it. The channel manager pushes ARI deltas to OTAs and sends OTA bookings back through the same booking path."),
    s(5, "Describe the schema for the inventory table and the hold records.", "The inventory table is keyed by hotel_id, room_type_id and stay_date. Its columns are physical_count, overbooking_allowance, sell_limit, held, sold and updated_at. A check constraint enforces held + sold <= sell_limit as a second safety net. The hold table stores hold_id, reservation_id, status (HELD, CONVERTED, RELEASED, EXPIRED), expires_at and created_at. A child table has one line per night, giving the room type, date and quantity. Reservations store the guest reference, rate plan, a snapshot of the cancellation policy, the quoted price for each night, status and the idempotency key under a unique index. I store per-night lines so that cancellations and modifications release exactly what was taken, even if the limits have changed since."),
    s(5, "The payment webhook arrives after the hold has already expired and been released. What do you do?", "The confirm step must never assume the hold is still alive. In one transaction I try to convert it with a conditional update: set status to CONVERTED only where status is HELD. If that affects zero rows, the hold is gone. Next I try to re-acquire every night with the same conditional update. If that succeeds, I convert and confirm. If any night fails, I mark the reservation FAILED. I then void the authorisation or refund the deposit and offer alternatives. Either way the invariant holds, because nothing is confirmed without inventory decremented for every night. I also alert when this happens often, since it suggests hold TTLs are shorter than real payment times."),
    s(4, "Why are search results labelled indicative, and how do you handle a guest who picks a room that is actually sold out?", "The search cache is updated asynchronously through the outbox and Kafka, so it lags the database by a short time. Making search strongly consistent would push enormous read traffic onto hot inventory rows, and most of those searches never become bookings. So I accept staleness on reads and enforce correctness only at hold time. When the conditional update fails for any night, the transaction rolls back and the guest sees alternatives straight away. These might be other room types, nearby hotels or flexible dates. I also make the failed hold trigger a targeted cache refresh for that hotel, so the next guest does not see the same stale result."),
    s(4, "How do you design idempotency across booking creation, payment and OTA ingestion?", "Each entry point has a natural key. Direct checkout uses a client-generated idempotency key stored under a unique index on reservations. A retry returns the existing reservation instead of creating a second one. OTA bookings use channel plus the OTA's booking id. Payment calls to the gateway pass our reservation-scoped idempotency key, so retries never double-charge. Webhooks are deduplicated by the gateway's event id in a processed-events table, written in the same transaction as the state change. Inside the saga, every step is a conditional state transition, such as HELD to CONVERTED. Replaying a step therefore does nothing. This matters because Kafka, the outbox relay and webhooks all deliver at least once."),
    s(4, "How is the overbooking allowance modelled, and what happens operationally when more guests arrive than rooms?", "Revenue management sets an allowance for each room type and date, based on its own forecast of no-shows and cancellations. We store it next to the physical count, and the sell limit is the sum of the two. The system enforces that limit strictly and never sells beyond it. The physical count still matters, because if sold exceeds it on the night of arrival, the front desk has a walk situation. We expose an oversold-risk report per night so staff can upgrade guests, move them to sister properties or arrange relocation under the hotel's policy. Allowance changes are audited. Lowering an allowance below the current sold count never cancels existing bookings. It only blocks new sales."),
    s(4, "Give me a back-of-the-envelope estimate for the load on search compared with booking.", "I would state my assumptions out loud rather than quote real figures. Say we have N hotels, each with about ten room types, and an 18-month booking window. Then inventory rows are roughly N × 10 × 540. For a hundred thousand hotels that is about 540 million rows, which a sharded relational store handles comfortably. Traffic is very read-heavy. If each booking comes from hundreds of searches, and each search checks many hotels and nights, search QPS is orders of magnitude above hold QPS. That is why search runs on a cache or search index that scales horizontally. The inventory database only sees holds, confirms, releases and ARI-driven updates, so it is sized for write contention, not read volume."),
    s(4, "A big concert drives thousands of checkouts at one hotel at the same moment. How do you handle hot-row contention?", "Each hold locks only a few rows, one per night, and does so briefly, so the transaction must stay tiny. There are no external calls inside it, and rows are locked in date order to avoid deadlocks. Under heavy contention the conditional update serialises requests on those rows, and losers fail fast instead of retrying in a loop. I would add admission control per hotel, such as a small queue or a rate limit in front of the hold endpoint, so the database is not overwhelmed. I would also short-circuit at the edge with a stale-but-recent sold-out flag. Other designs, such as pre-splitting stock into buckets, cost a lot in complexity and are rarely needed for hotels."),
    s(4, "How would you shard the inventory database?", "I shard by hotel_id. A stay is always for one hotel, so every room_type-night row for a hold sits on the same shard. That keeps the all-nights-or-nothing hold a single local transaction, with no distributed transaction at all. Reservations and holds for that hotel are co-located for the same reason. Hash-based sharding spreads popular cities evenly. I keep a directory or consistent hashing scheme so I can move very large chains or hot hotels without reshuffling everything. Cross-hotel queries, such as a chain's reporting or guest booking history, go to read replicas or analytics stores fed by the same Kafka events, not to the transactional shards."),
    s(4, "How does hold expiry work, and what if the delay queue loses or delays a message?", "When creating a hold we write expires_at and schedule a release message on the delay queue. When the message fires, the release runs one transaction. It sets status to EXPIRED only where status is still HELD, and if that succeeds it decrements held on every night. Running it twice does no harm. I never trust the queue alone. A periodic sweeper scans for holds where status is HELD and expires_at has passed, and releases them through the same code. So lost messages only delay the release a little. Late messages hit the conditional and do nothing if the hold was already converted. The search cache is also counted from held, so leaked holds would otherwise hide real stock."),
    s(3, "Rates differ per night. How do you price a multi-night stay and protect against price changes during checkout?", "Rates are stored per rate plan, room type and date, sometimes with length-of-stay or occupancy rules. At checkout the pricing service calculates a quote, which is a list of prices per night plus taxes and fees. We store it on the pending reservation with a quote id and an expiry. The amount charged is the stored quote, not a fresh lookup. That way a rate change in the middle of checkout cannot alter what the guest agreed to. If the quote expires before payment, we re-quote and show the guest any difference before charging. The cancellation policy is also stored as a snapshot on the reservation, so later edits to the rate plan never change an existing booking's terms."),
    s(4, "A guest changes their dates on a confirmed booking. How do you do it safely?", "I treat it as one inventory transaction on the hotel's shard. First I conditionally acquire every new night that is not already part of the booking. If any night fails, the whole thing rolls back and the original booking stays untouched. If all succeed, I release the nights that are no longer needed, update the reservation lines and write outbox events, all in the same commit. Overlapping nights are left as they are. This avoids a window where the guest holds nothing. Price differences and any modification fees are handled afterwards as a separate payment step that can be compensated. OTA modifications go through exactly the same path, keyed by the OTA's booking id plus a modification version."),
    s(4, "An OTA sends us a booking for a room-night we no longer have, because it hadn't received our last update. What happens?", "The OTA booking goes through the same conditional update as direct bookings, so our invariant is never broken by a channel. If the check fails, we reject or flag the booking according to that OTA's integration contract. Some channels accept a rejection, while others treat the booking as already confirmed to the guest. In the second case it lands in an exceptions queue for the hotel to resolve through relocation or by using spare overbooking allowance if revenue management permits. To make this rare, we push ARI updates quickly, prioritise close-outs over other updates, and keep a small buffer of stock off the channels near sell-out if the hotel chooses."),
    s(4, "How do you deal with ordering and duplicates when the outbox relay publishes to Kafka?", "The relay reads outbox rows in commit order and publishes them, but a crash can cause republishing, so delivery is at least once. I partition Kafka topics by hotel_id, or hotel plus room type, so events for the same inventory stay in order within a partition. Each event carries a monotonically increasing version for its room_type-night. Consumers keep the last version they applied and ignore older or duplicate ones. Where possible, events carry the absolute state, such as available = limit − held − sold, rather than deltas. That makes it safe to reapply them and lets a consumer recover just by reading the latest event."),
    s(3, "OTAs enforce rate limits on ARI pushes. How does the channel manager cope?", "I coalesce instead of forwarding every event. The channel manager keeps the latest desired state for each OTA, hotel, room type and date, and marks it dirty when an event arrives. A sender for each channel drains dirty keys within that channel's rate limit, batching dates into ranges where the OTA's API supports it. Ten quick changes to one night then become one push of the final value. Close-outs and low-availability updates get priority over rate tweaks. Failed pushes retry with backoff and jitter, and each attempt is logged for each channel so the hotel can see delivery status."),
    s(3, "How do you detect and fix drift between our inventory and what OTAs display?", "Incremental pushes can be lost, rejected or misapplied, so I add reconciliation. On a schedule, and on demand after incidents or a new mapping, the channel manager runs a full sync. It pushes the full ARI for a date window, which overwrites whatever the OTA holds. Where the OTA offers a read or reservation-retrieval API, we also pull its reservations and compare them with ours to find missed bookings or cancellations. Mismatches create tickets or trigger automatic re-ingestion through the idempotent booking path. Mapping errors, where an OTA room is linked to the wrong room type, are a common root cause, so mapping changes are validated and audited."),
    s(3, "Walk through cancellation, including what happens if the refund fails.", "The cancellation service evaluates the stored policy snapshot at the cancellation time, using the hotel's timezone. This gives free cancellation, a penalty or no refund. In one transaction it sets the reservation to CANCELLED conditionally, releases each night by decrementing sold, and writes outbox events. The room is back on sale quickly whether or not the refund has finished. The refund is a separate saga step, called with an idempotency key and retried with backoff. If it keeps failing, it goes to a finance exceptions queue, and we never re-sell or un-cancel the booking to fix it. The guest gets a notification with the refund status, and support can see the payment state."),
    s(4, "How do you handle card data securely in this flow?", "I keep our systems out of PCI DSS scope as far as possible. Card entry happens in the gateway's hosted fields or redirect page, and we receive only a token and the last digits. We never store the full card number, and we never store CVV after authorisation, which PCI DSS forbids. Webhooks are verified by signature and timestamp, and processed only once using the event id. Pay-at-hotel guarantees use network tokens or vaulted tokens. Card details are never passed to the hotel in plain text. Secrets for gateway and OTA APIs live in a secrets manager and are rotated. Access to payment admin tools needs strong authentication and is audited."),
    s(3, "What privacy obligations apply to guest data, and how do you design for them in India?", "Bookings hold personal data: names, contact details, sometimes ID documents, and stay history. India's Digital Personal Data Protection Act, 2023 requires a lawful basis, purpose limitation and security safeguards. It also requires honouring rights such as access and erasure, subject to legal retention needs such as tax records. In practice, I encrypt PII at rest, keep it in a guest service separate from inventory, and put only opaque guest ids in events. I share with OTAs and hotels only what the booking needs, set retention periods, and mask PII in logs. Guest registration and ID rules for hotels may add their own requirements, so I check with legal rather than assume."),
    s(3, "How do you handle time zones for stay dates and cancellation windows?", "A room-night is a calendar date in the hotel's local timezone, not a UTC instant. Inventory rows use a plain date type, and each hotel stores an IANA timezone id. Search converts the guest's chosen dates as dates and never shifts them through UTC. Cancellation deadlines, such as free cancellation until 6 pm the day before arrival, are calculated in the hotel's timezone and then stored as a UTC instant on the reservation for enforcement. Daylight-saving changes in some countries make this matter. Hold expiries and audit timestamps stay in UTC, because they are real instants rather than business dates."),
    s(3, "How is the search availability cache structured so it can answer 'every night has stock' quickly?", "Consumers update a key for each hotel, room type and date, holding available count and the best rate, in a store such as Redis or a search index. For a query, we first narrow hotels by city and party size using a geo or city index. Then, for each candidate room type, we fetch the nights in the range and check that the minimum available is at least one and that rules such as minimum stay pass. Many teams precompute a bitmap of available dates or a hotel-level summary so they can prune quickly before the detailed check. The price shown is the sum of nightly rates from the cache and is marked indicative. The real quote comes at checkout."),
    s(4, "Why not use a Redis distributed lock or Redis counters as the inventory source of truth?", "Redis locks with leases can be lost when a process pauses, a failover happens or the clock drifts. Two holders could then both believe they own the last room. Redis counters also cannot easily join a durable transaction with the hold record and the outbox row. The all-nights-or-nothing requirement and the outbox both need ACID atomicity in one store. A relational database's conditional update gives correctness without a separate lock service, and rows already serialise concurrent writers. I use Redis for the read cache and rate limiting, where staleness is acceptable, and keep the invariant in the database, where a crash cannot break it."),
    s(3, "Why use a saga here instead of a distributed two-phase commit?", "Two-phase commit needs every participant to support prepare and commit, and payment gateways and OTAs do not. It also holds locks while waiting for a coordinator, which is very costly on hot inventory rows when payments can take tens of seconds. A saga breaks the flow into local transactions with compensations: hold, then authorise, then convert. If authorisation fails we release the hold. If inventory is lost after payment we void or refund. The trade-off is that intermediate states, such as pending or held, are visible. So each step must be idempotent and recoverable, and a timeout-driven sweeper must finish or compensate any stuck saga."),
    s(4, "The gateway webhook never arrives. How does the booking avoid getting stuck?", "I never rely on webhooks alone. A saga timer runs for each pending reservation. If no webhook arrives within the expected window, a worker asks the gateway's payment-status API using our reference. If the payment succeeded, we run the same confirm logic as the webhook. If it failed, we release the hold. If it is still unclear, we extend the hold within a cap and keep polling. Webhook and poller both go through one idempotent confirm function, so whichever arrives second does nothing. Guests see a 'confirming your booking' state instead of a false failure, which also reduces duplicate retry bookings."),
    s(3, "How do deposit, full prepayment and pay-at-hotel rate plans change the flow?", "The rate plan's policy decides the payment step of the saga. For prepaid or deposit plans we capture an amount, either the full stay or a deposit, and confirm when we receive the success webhook. For pay-at-hotel with a card guarantee we may do a zero-value or small authorisation to verify the card and store a token, then confirm. Authorisations expire after a period set by the card network and issuer. So for long lead times we capture or re-authorise according to the policy rather than assume the authorisation lasts. Non-refundable plans capture in full immediately. In every variant, the inventory conversion happens in the same transaction as the status change to confirmed."),
    s(2, "How would you support a booking of several rooms, possibly of different room types?", "The hold becomes a multi-line hold. There is a quantity for each room type for each night, and the conditional update checks held + sold + qty <= limit. All lines across all room types and nights run in one transaction on the hotel's shard, locked in a fixed order by room type and then date to avoid deadlocks. The group is all-or-nothing by default. A guest can choose partial fulfilment, but only as an explicit option. Large group or allotment blocks for events are usually handled separately, as contracted allocations with release dates. Those reduce the sellable limit without creating individual bookings."),
    s(3, "The hotel marks rooms out of order, so physical count drops below what is already sold. What happens?", "Updating physical count recalculates the sell limit, but existing bookings are never cancelled automatically. The check constraint should therefore allow sold to exceed the limit, or the limit change should be done outside that constraint. Otherwise the update itself would fail. From then on, held + sold >= limit, so every new conditional update fails and the night is closed for sale. An outbox event pushes a close-out to the OTAs. The night appears on an oversold report so the front desk can plan moves or relocations. The change is audited with who made it and why, because it directly affects revenue and guest experience."),
    s(2, "How do you design for regional failure of the inventory database?", "Each shard runs a primary with synchronous or semi-synchronous replicas in other availability zones, so a zone failure costs no committed holds. For a full regional outage, an asynchronous cross-region replica can be promoted. I would only allow writes in one region per shard at a time, because running two active writers for the same rows would break the invariant. After failover, any recent commits that were not replicated create a reconciliation task against payment and OTA records. During an outage, search can keep serving from cache while checkout returns a clear 'try again shortly' message rather than taking payments it cannot back with inventory."),
    s(3, "Which metrics and alerts would you put on this system?", "For correctness, I would run an invariant checker that alerts on any row where held + sold > limit. I would also check for confirmed reservations missing per-night lines and for sold counts that disagree with the bookings summed per night. For flow health, I would track hold success rate, hold-expired-before-payment rate, saga time-to-confirm, stuck pending sagas, refund failures and outbox relay lag. For channels, I would watch ARI push latency and errors per OTA, OTA bookings rejected for lack of stock, and reconciliation mismatches. For performance, I would watch search latency, cache staleness and lock wait time on inventory shards. Each alert links to a runbook."),
    s(2, "How would you test that the system never oversells?", "I would start with property-based and concurrency tests. They fire many parallel holds, modifications and cancellations at one room-night, then assert that held + sold never exceeds the limit and that every confirmed booking has every night decremented. I would add fault injection. That means killing the service between hold and confirm, duplicating webhooks and Kafka messages, dropping delay-queue messages and delaying the gateway, then checking that sweepers and idempotency recover correctly. In staging I would replay recorded OTA traffic. In production the invariant checker and reconciliation jobs act as continuous tests. Formal models such as TLA+ can help for the saga state machine if the team has the skills."),
  ],
  objective: [
    o(5, "Which SQL statement correctly holds qty rooms for one room_type-night without overselling?", ["SELECT held, sold FROM inv WHERE id = :id; then UPDATE inv SET held = held + :qty in application code","UPDATE inv SET held = held + :qty WHERE id = :id AND held + sold + :qty <= sell_limit","UPDATE inv SET held = :new_value WHERE id = :id","INSERT INTO holds VALUES (...) and check the totals in a nightly batch job"], 1, "The condition and the increment run atomically in one statement, so concurrent writers cannot both pass the check."),
    o(5, "A guest checks in on the 10th and checks out on the 13th. How many room_type-night rows must the hold decrement?", ["4","2","1","3"], 3, "The guest occupies the nights of the 10th, 11th and 12th. The checkout date is not a night of the stay."),
    o(4, "How should the inventory service avoid deadlocks when two multi-night holds overlap?", ["Lock the rows in a consistent order, such as by room type and then by date","Use a longer lock timeout","Lock the rows in the order the guest selected the dates","Retry every transaction exactly three times"], 0, "Acquiring locks in the same global order removes the circular waits that cause deadlocks."),
    o(4, "What is the sell limit for a room_type-night in this design?", ["The physical room count only","The physical room count plus the overbooking allowance for that room type and date","Whatever each OTA requests","The physical count multiplied by the average occupancy"], 1, "Revenue management sets an allowance for each room type and date, and it is added to the physical count."),
    o(5, "When should the booking be marked CONFIRMED?", ["When the hold succeeds","When the guest clicks Pay","After the gateway's success webhook, in the same transaction that converts the hold to sold","After the confirmation email is sent"], 2, "Confirmation must be atomic with the inventory conversion and must come after verified payment success."),
    o(4, "Which idempotency key should be used for a reservation coming from an OTA?", ["Our auto-increment reservation id","The guest's email address","A hash of the check-in date","The channel identifier plus the OTA's booking id"], 3, "The OTA's booking id is stable across retries. Scoping it by channel avoids collisions between different OTAs."),
    o(4, "A hold-release message arrives after the hold was already converted to sold. What should happen?", ["Nothing, because the release only acts if the hold status is still HELD","Decrement held anyway","Cancel the booking","Move the message to a dead-letter queue and page on-call"], 0, "A conditional state transition makes the release idempotent and safe against late messages."),
    o(4, "Why is a periodic sweeper still needed alongside the delay queue for hold expiry?", ["The delay queue cannot hold messages longer than one second","Delay-queue messages can be lost or delayed, and the sweeper releases expired holds anyway","The sweeper confirms bookings","Sweepers are needed to update the OTAs"], 1, "A sweeper that checks expires_at guarantees that leaked holds are eventually released."),
    o(4, "Why is it acceptable for the search cache to be slightly stale?", ["Guests never book rooms they have searched for","Kafka guarantees exactly-once delivery","The cache is updated synchronously","The conditional update at hold time re-checks real inventory before anything is sold"], 3, "Correctness is enforced on the write path, so stale reads can only lead to a failed hold, never to an oversell."),
    o(4, "What delivery guarantee should consumers assume from the outbox relay to Kafka?", ["At-least-once, so consumers must be idempotent","At-most-once","Exactly-once, with no need for deduplication","Best-effort with no retries"], 0, "The relay can republish a row after a crash, so duplicates are possible and consumers must handle them."),
    o(3, "Which Kafka partition key preserves the order of inventory events for a hotel's room-nights?", ["A random UUID for each event","The event timestamp","The hotel_id, or hotel_id plus room type","The guest_id"], 2, "Kafka orders events only within a partition, so events for the same inventory must share a key."),
    o(3, "In hotel distribution, what does ARI stand for?", ["Automated Reservation Interface","Availability, Rates and Inventory","Allocation, Refunds and Invoicing","Average Room Income"], 1, "ARI is the standard term for the availability, rates and inventory data pushed to channels."),
    o(4, "Under PCI DSS, which card data must never be stored after authorisation?", ["The last four digits","The cardholder's name","The gateway token","The CVV/CVC security code"], 3, "PCI DSS prohibits storing sensitive authentication data such as the card verification code after authorisation."),
    o(3, "Which Indian law mainly governs how guest personal data is processed?", ["The Digital Personal Data Protection Act, 2023","The Payment and Settlement Systems Act, 2007 only","The Companies Act, 2013","The Indian Contract Act, 1872 only"], 0, "The DPDP Act, 2023 is India's general law on processing digital personal data."),
    o(3, "How should stay_date be stored on inventory rows?", ["As a UTC timestamp at midnight","As a calendar date in the hotel's local timezone","As the guest's local time","As epoch milliseconds"], 1, "A room-night is a business date at the property. Shifting it through UTC can move it to a different day."),
    o(3, "In PostgreSQL under READ COMMITTED, why is UPDATE ... WHERE held + sold + :qty <= sell_limit safe against races?", ["READ COMMITTED prevents all anomalies","PostgreSQL ignores the WHERE clause on locked rows","The second writer waits for the row lock, then re-checks the WHERE condition against the newly committed row","The statement always runs at SERIALIZABLE isolation"], 2, "PostgreSQL re-evaluates the condition against the latest committed version of the row after acquiring the lock."),
    o(4, "Which shard key keeps the all-nights-or-nothing hold a single local transaction?", ["stay_date","guest_id","city","hotel_id"], 3, "Every night of a stay belongs to one hotel, so sharding by hotel keeps all the rows on one shard."),
    o(3, "A guest changes their dates. What is the safest inventory approach?", ["Cancel the old booking first, then try to book the new dates","Acquire the new nights and release the dropped nights in one transaction, rolling back entirely if any new night fails","Only update the dates on the reservation row","Ask the hotel to adjust inventory by hand"], 1, "A single atomic swap means the guest never loses their original booking if the new dates are unavailable."),
    o(3, "Why is a saga preferred over two-phase commit for hold, payment and confirm?", ["External payment gateways do not take part in 2PC, and 2PC holds locks for a long time","Sagas guarantee isolation between steps","2PC cannot work with relational databases","Sagas need no compensation logic"], 0, "A saga uses local transactions with compensations, which suits external systems and keeps lock times short."),
    o(3, "An OTA enforces strict rate limits. How should the channel manager send ARI updates?", ["Forward every Kafka event immediately","Push only once a day","Coalesce to the latest state for each key, batch date ranges, and prioritise close-outs","Stop pushing until the rate limit resets"], 2, "Coalescing removes intermediate values and stays within limits while urgent sell-outs still go out first."),
    o(3, "What is the main purpose of a periodic full ARI sync to OTAs?", ["To reduce database storage","To fix drift caused by lost, rejected or misapplied incremental updates","To replace the outbox","To refresh guest PII"], 1, "Overwriting the OTA's state with our source of truth repairs any divergence."),
    o(2, "A guest cancels and the refund API keeps failing. What should happen to the released inventory?", ["It should stay released, while the refund is retried or escalated separately","It should be re-held until the refund succeeds","The booking should be reinstated","The night should be closed on every OTA"], 0, "Inventory release and refund are separate saga steps. A refund failure should not take a room off sale."),
    o(3, "How should the system verify a payment gateway webhook?", ["Check that the request comes from any HTTPS source","Trust it if the amount matches","Accept it if it contains the reservation id","Verify the gateway's signature and timestamp, and deduplicate by event id"], 3, "Signature verification prevents forged confirmations, and deduplication by event id makes processing idempotent."),
    o(3, "No webhook arrives within the expected time for a pending payment. What is the best action?", ["Confirm the booking anyway","Query the gateway's payment-status API and confirm or compensate through the same idempotent logic","Cancel immediately and charge again","Wait indefinitely"], 1, "Polling recovers lost webhooks, and sharing one idempotent confirm function avoids double processing."),
    o(3, "Rooms are marked out of order, so the sell limit drops below the current sold count. What happens to new hold attempts?", ["They succeed because the old bookings are grandfathered","Existing bookings are auto-cancelled to make room","They fail, because held + sold already meets or exceeds the limit","The limit is reset to the physical count plus 10%"], 2, "The conditional update blocks further sales, and existing bookings are handled operationally."),
    o(2, "Which check best detects an inventory invariant violation in production?", ["The average hold latency","The number of searches per minute","The Kafka consumer group count","Any row where held + sold > sell_limit"], 3, "That condition directly expresses the overselling the system must never allow."),
    o(2, "What is the main drawback of optimistic version-column updates on a very hot room-night?", ["They cannot detect conflicts","Many conflicts lead to repeated retries and wasted work","They need two-phase commit","They store card data"], 1, "Under heavy contention most optimistic attempts fail and retry, while a conditional update simply serialises the writers."),
    o(2, "For a multi-room group booking, how should the hold check quantity?", ["held + sold + qty <= sell_limit for every room type and night, in one transaction","Check one room at a time in separate transactions","Check only the first night","Check the total rooms across the whole hotel"], 0, "One all-or-nothing transaction with the quantity included prevents partial or oversold groups."),
    o(3, "Why should the pending reservation store the quoted per-night prices and a policy snapshot?", ["So search can read them","So OTAs can change them","So a rate or policy change during or after checkout does not alter what the guest agreed to","Because rates are never stored anywhere else"], 2, "Snapshots fix the commercial terms at booking time, which prevents disputes and mismatched charges."),
    o(2, "An OTA booking fails the inventory check, but the OTA treats it as already confirmed to the guest. What is the best handling?", ["Silently drop it","Force sold above the limit automatically","Retry the conditional update until it succeeds","Send it to an exceptions queue for the hotel to resolve, without breaking the invariant automatically"], 3, "Humans resolve the conflict through relocation or an approved allowance change, while the automated invariant stays intact."),
  ],
};
export default bank;
